use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// The hosts the `HTTPClient` handle is scoped to. A request outside this set
/// is a trap at the boundary, not a value, so the guest must never send one.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

struct Node;

/// True only if `url` is an absolute http(s) URL whose host is exactly one of
/// `ALLOWED_HOSTS`. Anything the host might interpret differently (userinfo,
/// ports, percent-escapes, backslashes, whitespace, non-ASCII) is refused here,
/// so the guest never makes a request the host would trap on.
fn allowed_host(url: &str) -> bool {
    if url.bytes().any(|b| b <= b' ' || b >= 0x7f) {
        return false;
    }

    let rest = match url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))
    {
        Some(r) => r,
        None => return false,
    };

    let end = rest
        .find(|c: char| matches!(c, '/' | '?' | '#'))
        .unwrap_or(rest.len());
    let authority = rest[..end].to_ascii_lowercase();

    if authority.is_empty()
        || !authority
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'.' || b == b'-')
    {
        return false;
    }

    ALLOWED_HOSTS.contains(&authority.as_str())
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            if !allowed_host(&url) {
                failures.push(FetchFailure {
                    url,
                    error: "refused: host not in allowlist".to_string(),
                });
                continue;
            }

            // `fetch` returns transport failures as values; only out-of-scope
            // requests trap, and the check above keeps those from happening.
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
